mkdir -p src/routes/books && cat > src/components/book-list.kay <<'EOF'
---
import { favorites, isFavorite } from '../favorites'

interface BookSummary { slug: string, title: string, author: string, year: number, tags: string[] }

const { books, tags } = props<{ books: BookSummary[], tags: string[] }>()
const selected = signal<string | undefined>(undefined)
const shown = memo(() => {
  const tag = selected()
  return tag === undefined ? books : books.filter(book => book.tags.includes(tag))
})
---
.tag-filter(role="group" aria-label="Filter by tag")
  button(
    type="button"
    aria-pressed={selected === undefined ? 'true' : 'false'}
    onClick={() => selected.set(undefined)}
  )
    | All
  for tag of tags
    button(
      type="button"
      aria-pressed={selected === tag ? 'true' : 'false'}
      onClick={() => selected.set(tag)}
    )
      | {tag}
ul(aria-label="Books")
  for book of shown key={book.slug}
    li
      a(href={`/books/${book.slug}`}) {book.title}
      | 
      span {book.author}, {book.year}
      if isFavorite(favorites(), book.slug)
        | 
        strong.favorite Favorite
EOF
cat > src/routes/books/index.kay <<'EOF'
--- server
import { books } from '../../content.config'
import BookList from '../../components/book-list.kay'

const list = (await books.all()).map(book => ({
  slug: book.slug,
  title: book.data.title,
  author: book.data.author,
  year: book.data.year,
  tags: book.data.tags,
}))
const tags = [...new Set(list.flatMap(book => book.tags))].toSorted((a, b) => a.localeCompare(b, 'en'))
---
head
  title Books
h1 All books
BookList(books={list} tags={tags})
EOF
cat > src/components/favorite-button.kay <<'EOF'
---
import { favorites, isFavorite } from '../favorites'

const { slug } = props<{ slug: string }>()
const favorite = memo(() => isFavorite(favorites(), slug))

function toggle() {
  const current = Array.isArray(favorites()) ? favorites() : []
  favorites.set(favorite() ? current.filter(item => item !== slug) : [...current, slug])
}
---
button(type="button" onClick={toggle})
  | {favorite ? 'Remove from favorites' : 'Add to favorites'}
EOF
